import { describe, expect, it } from 'vitest';

import {
  expectError,
  governedHarness,
  jsonReply,
  submitRequest,
} from './governed-review-submit.test-support';

/**
 * BE03c 1298-1302: a response with an unmapped status or a message not generated by
 * the operation catalog is a contract failure -> scrubbed 500. A PostgREST or
 * PostgreSQL fault is not the caller's refusal, whatever its HTTP status.
 */
const PROVIDER_FAULTS: readonly (readonly [string, number, unknown])[] = [
  [
    'PGRST202 function not found (RPC missing or unexposed)',
    404,
    {
      code: 'PGRST202',
      message:
        'Could not find the function platform_api.cms_submit_governed_review',
      details: 'private provider',
    },
  ],
  [
    'PGRST301 bad service credential',
    401,
    { code: 'PGRST301', message: 'JWT expired' },
  ],
  [
    'SQLSTATE 42702 ambiguous column',
    400,
    {
      code: '42702',
      message: 'column reference "actor_id" is ambiguous',
      details: 'private provider',
    },
  ],
  ['SQLSTATE 23505 unique violation', 409, { code: '23505', message: 'x' }],
  [
    'SQLSTATE 40001 engine serialization failure',
    409,
    { code: '40001', message: 'could not serialize access' },
  ],
  ['SQLSTATE 42501 insufficient privilege', 403, { code: '42501' }],
  ['PGRST116 row count', 422, { code: 'PGRST116', message: 'x' }],
  ['provider rate limit without a token', 429, { message: 'slow down' }],
  ['payload without any code', 404, { message: 'NOT_FOUND' }],
  ['numeric code', 400, { code: 42702, message: 'x' }],
  ['unsupported 4xx status', 418, { code: 'PGRST999' }],
  ['array payload', 400, ['NOT_FOUND']],
  ['string payload', 404, 'NOT_FOUND'],
  ['null payload', 400, null],
];

describe('CMS-03C-06 provider 4xx without a product token (BE03c 1298-1302)', () => {
  it.each(PROVIDER_FAULTS)(
    'scrubs %s to 500 INTERNAL_ERROR',
    async (_name, status, payload) => {
      const harness = governedHarness({
        reply: () => jsonReply(payload, status),
      });
      const error = await expectError(
        await harness.send(submitRequest()),
        500,
        'INTERNAL_ERROR',
      );
      expect(error.details).toEqual({});
      expect(harness.fetchImpl).toHaveBeenCalledTimes(1);
    },
  );

  it('does not let a faulting status borrow a refusal from the message prose', async () => {
    const harness = governedHarness({
      reply: () =>
        jsonReply(
          {
            code: 'PGRST202',
            message: 'capability_missing NOT_FOUND',
            details: 'subject_not_submittable',
          },
          404,
        ),
    });
    await expectError(
      await harness.send(submitRequest()),
      500,
      'INTERNAL_ERROR',
    );
  });

  it.each([
    [
      'structured NOT_FOUND',
      404,
      { code: 'NOT_FOUND' },
      404,
      'GOVERNED_REVIEW_NOT_FOUND',
    ],
    [
      'P0001 NOT_FOUND',
      400,
      { code: 'P0001', message: 'NOT_FOUND' },
      404,
      'GOVERNED_REVIEW_NOT_FOUND',
    ],
    [
      'structured INVALID_REQUEST',
      400,
      { code: 'INVALID_REQUEST' },
      400,
      'INVALID_REQUEST',
    ],
    [
      'P0001 subject_not_submittable',
      400,
      { code: 'P0001', message: 'subject_not_submittable' },
      409,
      'GOVERNED_REVIEW_VERSION_CONFLICT',
    ],
    [
      '40001 VERSION_MISMATCH',
      409,
      { code: '40001', message: 'VERSION_MISMATCH' },
      409,
      'GOVERNED_REVIEW_VERSION_CONFLICT',
    ],
  ] as const)(
    'keeps the product answer for %s',
    async (_name, providerStatus, payload, status, code) => {
      const harness = governedHarness({
        reply: () => jsonReply(payload, providerStatus),
      });
      await expectError(await harness.send(submitRequest()), status, code);
    },
  );
});
